import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The statements taken of each person, kept per sheet in the order they were taken. */
@Repository
public class StatementStore {

    private final JdbcTemplate jdbc;

    public StatementStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void add(String sheetId, Statement statement, String user) {
        jdbc.update("INSERT INTO statement (sheet_id, person_id, taken_on, due_total, claims, taken_by) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, statement.personId(), Date.valueOf(statement.takenOn()), statement.dueTotal(),
                statement.claims(), user);
    }

    /** Gives the statements of {@code fromId} on {@code fromSheet} to {@code intoId} on {@code toSheet}, after the
     *  ones {@code intoId} has, but keeps the last of {@code intoId}'s statements their last (when they have none,
     *  the last of the others becomes theirs). The statements of {@code fromId} are dropped with them (see
     *  PersonStore). */
    public void moveAll(String fromSheet, long fromId, String toSheet, long intoId) {
        var last = jdbc.queryForList("SELECT id FROM statement WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC LIMIT 1",
                Long.class, toSheet, intoId);
        jdbc.update("INSERT INTO statement (sheet_id, person_id, taken_on, due_total, claims, taken_by) "
                + "SELECT ?, ?, taken_on, due_total, claims, taken_by FROM statement WHERE sheet_id = ? AND person_id = ? "
                + "ORDER BY id", toSheet, intoId, fromSheet, fromId);
        if (!last.isEmpty()) {
            // listed by id: taken again after the others, so it stays their last
            jdbc.update("INSERT INTO statement (sheet_id, person_id, taken_on, due_total, claims, taken_by) "
                    + "SELECT sheet_id, person_id, taken_on, due_total, claims, taken_by FROM statement WHERE id = ?",
                    last.get(0));
            jdbc.update("DELETE FROM statement WHERE id = ?", last.get(0));
        }
    }

    /** Removes the person's last statement and returns it, or null when they have none. */
    public Statement removeLast(String sheetId, long personId) {
        var ids = jdbc.queryForList("SELECT id FROM statement WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC LIMIT 1 FOR UPDATE",
                Long.class, sheetId, personId);
        if (ids.isEmpty()) {
            return null;
        }
        Statement last = jdbc.queryForObject("SELECT taken_on, due_total, claims FROM statement WHERE id = ?",
                (rs, i) -> new Statement(personId, rs.getObject("taken_on", LocalDate.class), rs.getBigDecimal("due_total"),
                        rs.getInt("claims")), ids.get(0));
        jdbc.update("DELETE FROM statement WHERE id = ?", ids.get(0));
        return last;
    }

    /** Each person on the sheet with a statement: their count and last statement. */
    public Map<Long, StatementSummary> summaries(String sheetId) {
        return summariesFrom(sheetId, "statement");
    }

    /** Each person on the sheet with a statement as the statements stood at the end of the date (see
     *  {@link History}): their count and last statement then. */
    public Map<Long, StatementSummary> summariesAsOf(String sheetId, LocalDate date) {
        return summariesFrom(sheetId, History.asOf("statement", "id", date));
    }

    private Map<Long, StatementSummary> summariesFrom(String sheetId, String table) {
        Map<Long, List<StatementSummary.Line>> lines = new HashMap<>();
        jdbc.query("SELECT person_id, taken_on, due_total FROM " + table + " WHERE sheet_id = ? ORDER BY id",
                rs -> {
                    lines.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new StatementSummary.Line(
                            rs.getObject("taken_on", LocalDate.class).toString(), figure(rs.getBigDecimal("due_total"))));
                }, sheetId);
        Map<Long, StatementSummary> found = new HashMap<>();
        jdbc.query("SELECT s.person_id, s.taken_on, s.due_total, c.n FROM (SELECT * FROM " + table + ") s JOIN "
                + "(SELECT person_id, COUNT(*) AS n, MAX(id) AS last_id FROM " + table + " WHERE sheet_id = ? GROUP BY person_id) c "
                + "ON s.id = c.last_id", rs -> {
                    long personId = rs.getLong("person_id");
                    found.put(personId, new StatementSummary(rs.getInt("n"), figure(rs.getBigDecimal("due_total")),
                            rs.getObject("taken_on", LocalDate.class).toString(),
                            List.copyOf(lines.getOrDefault(personId, List.of()))));
                }, sheetId);
        return found;
    }

    private static String figure(BigDecimal total) {
        return total == null ? "n/a" : total.setScale(2).toPlainString();
    }

    public StatementSummary summary(String sheetId, long personId) {
        return summaries(sheetId).getOrDefault(personId, StatementSummary.NONE);
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.claim.Lateness;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes a statement of the person on the sheet's today: their due-total (the sum of the figures of
 *  their claims that count; n/a when their grade in force today has no rate today and no counting claim
 *  keeps a fixed figure or a figure at another grade, the one in force on its date), binding each counting claim to its due as shown now, late charge and floor included (a claim already bound
 *  keeps the due it was bound to) and unbinding the rest. A settled claim keeps its fixed figure. The due-total is
 *  at most the sheet's cap.
 *  <p>
 *  Taken as of a date (on or before the sheet's today), everything is as it stood at the end of that date
 *  (see {@link net.officefloor.hq.app.history.History}): their claims that counted then are bound to their
 *  figures then, and the date stands in for the sheet's today in every figure (grade and rate in force, floor,
 *  late charges, holds, retirement, cap); every other claim of theirs is unbound. The statement is dated that
 *  date. Refused when the date is after the sheet's today, or the person was not on the sheet then. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, ClaimStore claims, RateStore rates,
            SheetStore sheets, SettingStore settings, PersonStore people, StatementStore statements,
            Out<Statement> statementOut) throws InvalidSheetException {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        LocalDate asOf = request.asOfDate();
        if (asOf != null && asOf.isAfter(today)) {
            throw new InvalidSheetException("The statement date is after the sheet's today");
        }
        // Locked, so a status change or another statement made at once waits for this one.
        List<Claim> bound = claims.listForUpdate(sheetId, person.getId());
        // What the figures follow: the store as it is now, or as it stood at the end of the date.
        LocalDate on = today;
        Person then = person;
        List<Claim> all;
        Map<Long, Claim> was = new HashMap<>();
        if (asOf == null) {
            all = claims.list(sheetId);
            bound.forEach(claim -> was.put(claim.getId(), claim));
        } else {
            on = asOf;
            then = people.findAsOf(sheetId, person.getId(), asOf);
            if (then == null) {
                throw new InvalidSheetException("The person was not on the sheet on " + asOf);
            }
            rates = rates.asOf(asOf);
            settings = settings.asOf(asOf);
            all = claims.listAsOf(sheetId, asOf);
            all.stream().filter(claim -> claim.getPersonId() == person.getId()).forEach(claim -> was.put(claim.getId(), claim));
        }
        LocalDate policy = settings.policyDate(sheetId);
        Rounding rounding = new Rounding(policy != null ? policy : on, settings.roundings(sheetId), all);
        Person whose = then;
        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), on, rounding,
                Lateness.graced(settings.graces(sheetId), id -> id == whose.getId() ? whose : null));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int counted = 0;
        for (Claim live : bound) {
            // The claim as it stood then (itself when taken now); null when it was not theirs then.
            Claim claim = was.get(live.getId());
            // An OPEN (or PENDING) claim dated within a hold counts in no live total unless a statement bound
            // it, so a statement neither counts nor binds it; one it bound before stays counted. A deferred
            // claim counts in no total until the sheet's today reaches its date: a statement leaves it unbound.
            boolean counts = claim != null && RollupService.counts(claim, then, on);
            BigDecimal figure = null;
            boolean na = false;
            if (counts) {
                figure = ClaimFigure.of(claim, rates.forClaim(claim).find(sheetId, then.gradeOn(claim.getDate()), claim.getDate()), rounding);
                counted++;
                if (figure != null) {
                    // Bound as shown: its charge and floor stop following the sheet's today.
                    figure = lateness.dueOf(claim, figure);
                    total = total.add(figure);
                }
                // A figure at a grade other than the one in force today, or at a rate that ended before
                // today, does not hang on today's grade's rate.
                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
                        || (figure != null && (!then.gradeOn(claim.getDate()).equals(then.gradeOn(on))
                                || rates.forClaim(claim).endsBefore(sheetId, then.gradeOn(claim.getDate()), claim.getDate(), on)));
                // A claim whose rate ended before its date is bound to n/a, so a later rate leaves it so.
                na = figure == null && (claim.isBound()
                        || (claim.getSettledDue() == null && rates.forClaim(claim).ended(sheetId, then.gradeOn(claim.getDate()), claim.getDate())));
            }
            live.setStated(counts);
            live.setStatedDue(figure);
            live.setStatedNa(na);
            claims.bind(live);
        }
        boolean na = rates.find(sheetId, then.gradeOn(on), on) == null && !fixed;
        Statement statement = new Statement(person.getId(), on,
                na ? null : SettingStore.capped(total, settings.cap(sheetId)), counted);
        statements.add(sheetId, statement, request.user());
        statementOut.set(statement);
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken of a person: their due-total then (null when it was n/a), how many of their
 *  claims counted, and the sheet's today when it was taken. */
public record Statement(long personId, LocalDate takenOn, BigDecimal dueTotal, int claims) {
}
-- A person's statements: each records their due-total at that moment (null when it was n/a), how
-- many of their claims counted then, and the sheet's today when it was taken. Listed by id.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255)   NOT NULL,
    person_id BIGINT         NOT NULL,
    taken_on  DATE           NOT NULL,
    due_total DECIMAL(19, 2),
    claims    INT            NOT NULL,
    taken_by  VARCHAR(255)
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement: it shows and totals stated_due (the figure it had
-- then; null when it had none, n/a) until their next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);

